# .reviewer-config.sh — claude-code-reviewer configuration
# Generated by install.sh on 2026-10-19
# Edit to match your project. Source: https://github.com/jazzsequence/claude-code-reviewer

REVIEWER_TEST_CMD="pnpm test"
REVIEWER_LINT_CMD="pnpm lint && pnpm typecheck"
REVIEWER_BUILD_CMD="pnpm build"
REVIEWER_E2E_CMD=""

REVIEWER_MAX_FILES=5
REVIEWER_MAX_INSERTIONS=500
REVIEWER_APPROVAL_TIMEOUT=300
REVIEWER_APPROVAL_FILE="reviewer-approved"

REVIEWER_TEXT_ONLY_PATTERN='\.(md|mdx|txt|rst)$|^\.(claude|githooks)/'
REVIEWER_EXCLUDED_FILES='^package-lock\.json$|^yarn\.lock$|^pnpm-lock\.yaml$|^composer\.lock$|^Gemfile\.lock$'
